#!/usr/bin/env bash
# L-SI box 84 milestone 3 self-check: pins; LOW instances regenerated byte-equal; meas83 and lb84 (LOWER-BLIND, keep form) re-run, diffed.
set -euo pipefail
cd "$(dirname "$0")"
sha1sum -c --quiet --strict pins.sha1
t=$(mktemp -d); mkdir -p "$t/inst"; bash mkinst_m3.sh "$t/inst"
for i in LO2_priv LO2_nopriv; do
  cmp -s "$t/inst/$i.json" inst/$i.json
  python3 -I -B ../../box83/meas83.py inst/$i.json ../../box81 -v > "$t/m"; diff -q "$t/m" out/meas_$i.out
done
python3 -I -B lb84.py ../../box81 ../../box83/inst/LR3_exitup.json ../../box83/inst/LR6_exitup.json ../inst/HP3_mup.json ../inst/HP4_mup.json ../inst/HP5_mup.json ../m2/inst/CY3_hp.json ../m2/inst/CY4_hp.json ../../box81/inst/RS2.json ../../box81/inst/RS2_L8M6.json ../../box81/inst/RSG_K4.json inst/LO2_priv.json inst/LO2_nopriv.json > "$t/l"; diff -q "$t/l" out/lb84.out
! grep -v "mispredictions 0 " out/lb84.out
rm -rf "$t"
echo "box 84 m3 checks: PASS"
